<?php
require_once __DIR__ . '/../includes/auth.php';$u=require_role(['admin','superadmin']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$img=upload_item_image();$s=$pdo->prepare("INSERT INTO found_items(item_name,category,description,color,quantity,has_items_inside,image_path,location_found,date_found,recorded_by) VALUES(?,?,?,?,?,?,?,?,?,?)");$s->execute([trim($_POST['item_name']),trim($_POST['category']),trim($_POST['description']),trim($_POST['color']),max(1,(int)$_POST['quantity']),isset($_POST['has_items_inside'])?1:0,$img,trim($_POST['location_found']),$_POST['date_found'],$u['id']]);log_audit($pdo,'ADD_FOUND_ITEM','found_item',(int)$pdo->lastInsertId(),'Office found-item record');}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$pdo->query("SELECT f.*,a.full_name AS recorder FROM found_items f LEFT JOIN accounts a ON a.id=f.recorded_by ORDER BY f.created_at DESC")->fetchAll();page_header('Found Items');?><h1>Office Found Items</h1><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><div class="panel"><div class="panel-head">Record an Item Found</div><div class="panel-body"><form method="post" enctype="multipart/form-data"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Item Name *</label><input name="item_name" required></div><div class="field"><label>Category</label><input name="category"></div><div class="field"><label>Color</label><input name="color"></div><div class="field"><label>Quantity</label><input type="number" min="1" name="quantity" value="1"></div><div class="field"><label>Location Found *</label><input name="location_found" required></div><div class="field"><label>Date Found *</label><input type="date" name="date_found" required></div><div class="field wide"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Picture</label><input type="file" name="image"></div></div><button>Save Found Record</button></form></div></div><div class="table-wrap"><table><tr><th>Item</th><th>Category</th><th>Location</th><th>Date Found</th><th>Recorded By</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['item_name'])?></td><td><?=e($r['category'])?></td><td><?=e($r['location_found'])?></td><td><?=e($r['date_found'])?></td><td><?=e($r['recorder']??'—')?></td></tr><?php endforeach;?></table></div><?php page_footer();?>
